const T = (a, b) => rango(a, b);
const todos = (a, b, dom) => horario({ 0: dom ?? T(a, b), 1: T(a, b), 2: T(a, b), 3: T(a, b), 4: T(a, b), 5: T(a, b), 6: T(a, b) });
const lunSab = (a, b, dom) => horario({ 0: dom ?? null, 1: T(a, b), 2: T(a, b), 3: T(a, b), 4: T(a, b), 5: T(a, b), 6: T(a, b) });

